package com.fitnutri.backend.activity.catalogue;
import com.fitnutri.backend.common.*;
import com.fitnutri.backend.user.User;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class ExerciseOptionControllerTest {
 @Test void boundedInputsRejectBeforeQueriesAndDatabaseFailureIsNotAnEmptyResult(){var jdbc=mock(JdbcTemplate.class);var json=new tools.jackson.databind.ObjectMapper();var options=new ExerciseOptionService(jdbc,json);var movements=new MovementCatalogueService(jdbc,json);for(String category:List.of("UNKNOWN","cardio"))assertThrows(BusinessException.class,()->options.search(category,"bike",0,20));for(String q:List.of("x".repeat(81),"%"))assertThrows(BusinessException.class,()->options.search(null,q,0,20));assertThrows(BusinessException.class,()->movements.search("INVALID",null,null,0,20));assertThrows(BusinessException.class,()->movements.search(null,"INVALID",null,0,20));assertThrows(BusinessException.class,()->options.search(null,null,-1,20));assertThrows(BusinessException.class,()->movements.search(null,null,null,0,101));verifyNoInteractions(jdbc);when(jdbc.queryForObject(anyString(),eq(Long.class))).thenReturn(0L);assertEquals("CATALOGUE_UNAVAILABLE",assertThrows(BusinessException.class,()->options.search(null,null,0,20)).code());when(jdbc.queryForObject(anyString(),eq(Long.class))).thenThrow(new org.springframework.dao.DataAccessResourceFailureException("private SQL sentinel"));var error=assertThrows(BusinessException.class,()->movements.search(null,null,null,0,20));assertEquals("CATALOGUE_UNAVAILABLE",error.code());assertFalse(error.getMessage().contains("private"));}
 @Test void typedFilterRoutesRequireCurrentUserAndArePrivate()throws Exception{var options=mock(ExerciseOptionService.class);var movements=mock(MovementCatalogueService.class);var current=mock(CurrentUserService.class);var user=new User();user.setId(42L);when(current.requireGeneralUser(null)).thenReturn(user);when(options.search("CARDIO","bike",0,20)).thenReturn(new ExerciseCataloguePage<>(List.of(),0,0,20,false));when(movements.search("CHEST","MACHINE","chest press",0,20)).thenReturn(new ExerciseCataloguePage<>(List.of(),0,0,20,false));var mvc=MockMvcBuilders.standaloneSetup(new ExerciseOptionController(options,movements,current)).setControllerAdvice(new ApiExceptionHandler()).build();mvc.perform(get("/api/v2/exercise/options").param("category","CARDIO").param("query","bike")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.totalMatches").value(0));mvc.perform(get("/api/v2/exercise/movements").param("bodyRegion","CHEST").param("equipment","MACHINE").param("query","chest press")).andExpect(status().isOk()).andExpect(jsonPath("$.results").isEmpty());verify(movements).search("CHEST","MACHINE","chest press",0,20);}
 @Test void incompatibleQueryFieldsDoNotGetReinterpretedAsCatalogueFilters()throws Exception{var options=mock(ExerciseOptionService.class);var movements=mock(MovementCatalogueService.class);var current=mock(CurrentUserService.class);var user=new User();user.setId(42L);when(current.requireGeneralUser(null)).thenReturn(user);var mvc=MockMvcBuilders.standaloneSetup(new ExerciseOptionController(options,movements,current)).setControllerAdvice(new ApiExceptionHandler()).build();mvc.perform(get("/api/v2/exercise/options").param("bodyRegion","CHEST")).andExpect(status().isBadRequest());mvc.perform(get("/api/v2/exercise/movements").param("met","99")).andExpect(status().isBadRequest());verifyNoInteractions(options,movements);}
}
